    app.listen(WORKTREE_CHANGED_EVENT, move |event: tauri::Event| {
        if let Ok(payload) = serde_json::from_str::<WorktreeChangedPayload>(event.payload()) {
            let _ = event_tx.try_send(payload);
        }
    });

